'use strict';
// 简易 got 替代模块 - 支持重定向
const http = require('http');
const https = require('https');

// 响应体大小上限（默认 20MB；防御恶意/异常接口超大响应致内存暴涨）
const DEFAULT_MAX_BODY = 20 * 1024 * 1024;

function request(url, options = {}, redirects = 5) {
    return new Promise((resolve, reject) => {
        // 协议相对(//host/x)无 base 时 new URL 抛 Invalid URL，补 http: 前缀
        const urlStr = typeof url === 'string' && url.startsWith('//') ? 'http:' + url : url;
        const urlObj = typeof urlStr === 'string' ? new URL(urlStr) : url;
        const mod = urlObj.protocol === 'https:' ? https : http;
        
        const opts = {
            hostname: urlObj.hostname,
            port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
            path: urlObj.pathname + urlObj.search,
            method: (options.method || 'GET').toUpperCase(),
            headers: options.headers || {},
            // timeout 防御：0/负数/非数字 → 默认 15s（0 若传 http.request 表示无超时，误配会挂死）
            timeout: (Number.isFinite(options.timeout) && options.timeout > 0) ? options.timeout : 15000,
        };

        if (!opts.headers['Content-Type']) {
            opts.headers['Content-Type'] = 'application/json';
        }

        const req = mod.request(opts, (res) => {
            // 处理重定向
            if ([301, 302, 303, 307, 308].includes(res.statusCode) && res.headers.location && redirects > 0) {
                const location = res.headers.location;
                // 绝对(http://)与协议相对(//host/x)保留原样；相对路径拼 origin（// 开头不能拼，会成 origin//host/x）
                const newUrl = (location.startsWith('http') || location.startsWith('//')) ? location : `${urlObj.origin}${location}`;
                return resolve(request(newUrl, options, redirects - 1));
            }

            let chunks = [];
            let total = 0;
            const maxBody = (Number.isFinite(options.maxBody) && options.maxBody > 0) ? options.maxBody : DEFAULT_MAX_BODY;
            res.on('data', chunk => {
                total += chunk.length;
                if (total > maxBody) {
                    req.destroy();
                    const err = new Error(`响应体过大(超过 ${maxBody} 字节)`);
                    err.code = 'EBODYLIMIT';
                    reject(err);
                    return;
                }
                chunks.push(chunk);
            });
            res.on('end', () => {
                const buf = Buffer.concat(chunks);
                const data = buf.toString('utf8');
                const result = {
                    body: data,
                    statusCode: res.statusCode,
                    headers: res.headers,
                };
                try { 
                    result.body = JSON.parse(data); 
                } catch(e) {
                    // 保持原始字符串
                }

                // 4xx/5xx 视为错误，附带 response 信息（供外层判断状态码）
                if (result.statusCode >= 400) {
                    const err = new Error(`HTTP ${result.statusCode}`);
                    err.response = {
                        statusCode: result.statusCode,
                        body: result.body,
                        headers: result.headers,
                    };
                    err.code = 'HTTP_' + result.statusCode;
                    reject(err);
                    return;
                }
                resolve(result);
            });
        });

        req.on('error', reject);
        req.on('timeout', () => { 
            req.destroy(); 
            const err = new Error('ETIMEDOUT');
            err.code = 'ETIMEDOUT';
            reject(err); 
        });

        if (options.json && opts.method !== 'GET') {
            req.write(JSON.stringify(options.json));
        } else if (options.body) {
            req.write(options.body);
        }
        req.end();
    });
}

// 主函数
function got(url, options) {
    const promise = request(url, options);
    promise.json = () => promise.then(r => {
        if (typeof r.body === 'object') return r.body;
        throw new Error('Response is not JSON: ' + r.body.slice(0, 100));
    });
    return promise;
}

got.get = (url, options) => got(url, { ...options, method: 'GET' });
got.post = (url, options) => {
    const promise = request(url, { ...options, method: 'POST' });
    promise.json = () => promise.then(r => {
        if (typeof r.body === 'object') return r.body;
        throw new Error('Response is not JSON: ' + r.body.slice(0, 100));
    });
    return promise;
};

module.exports = got;
